import java.util.*;

public class golf
{
	public static void main(String[] args)
	{	
                int 		numRolls = 0;
                int		player = 0;
                int[]		playerPosition = new int[2]; 
		UILFileReader 	input = new UILFileReader("golf.dat");
		
		while( input.ready())
		{	
                        player = 0;
                        numRolls = 0;
                        playerPosition[0] = 1;
                        playerPosition[1] = 1;

			numRolls = input.readInt();
          
                        for(int turn = 1; turn <= numRolls; turn++)
			{
                                if(turn%2 != 0)
                                {
					player = 0;
                                }  
                                else	player = 1;

                                int roll = input.readInt();

                                switch(roll)
                                {
                                	case 2:		roll = 9;
 							break;

 					case 3:		roll = -2;
							break;

					case 4:		roll = 2;
							break;

					case 5:		roll = 2;
							break;

					case 6:		roll = 1;
							break;
		
					case 7:		roll = -3;
							break;

					case 8:		roll = 1;
							break;

					case 9:		roll = -2;
							break;

					case 10:	roll = -2;
							break;

					case 11:	roll = 1;
							break;

					case 12:	roll = 1;
							break;

					default:	System.out.println("Error: " + roll + " is not a valid roll!");
							System.exit(1);
				}

                        	playerPosition[player] += roll;
                                
                                if(playerPosition[player] < 1)
                                {
                                	playerPosition[player] = 1;
                                }
                                else if(playerPosition[player] >= 10)
                                {
                                        player++;
                                	System.out.println("Player " + player + " wins!");

					if(turn != numRolls)
					{
                                        	input.readLine();
					}

                                        break;
                                }
			}
		}
	}

}

import java.io.*;

public class matrix {

   public static void main(String args[]) {
      int total_matrices;
      int matrix[][] = new int[10][];
      UILFileReader input = new UILFileReader("matrix.dat");

      for (int i=0; i<10; i++) {
          matrix[i] = new int[10];
      }

      /* Read the total number of matrices */
      total_matrices = input.readInt();

      /* Process that many matrices */
      for (int dataset=0; dataset<total_matrices; dataset++) {
         int size, sum = 0, temp_sum, temp_sum2;
         boolean magic;
         boolean number_used[] = new boolean[101];

         /* Read in this matrix's size */
         size = input.readInt();

         /* Read in the matrix */
         for (int row=0; row<size; row++) {
            for (int col=0; col<size; col++) {
               matrix[row][col]=input.readInt();
            }
         }

         /* Assume it's a magic square until we get a contradiction */
         magic = true;

         /* Check the rows */
         for (int row=0; row<size; row++) {
            temp_sum = 0;
            for (int col=0; col<size; col++) {
               temp_sum+=matrix[row][col];
            }
            if (row == 0) sum = temp_sum;
            else if (temp_sum != sum) magic = false;
         }

         /* Check the columns */
         for (int col=0; col<size; col++) {
            temp_sum=0;
            for (int row=0; row<size; row++) {
               temp_sum+=matrix[row][col];
            }
            if (temp_sum != sum) magic = false;
         }

         /* Check the diagonals */
         temp_sum = temp_sum2 = 0;
         for (int row=0; row<size; row++) {
            temp_sum += matrix[row][row];
            temp_sum2 += matrix[row][(size-1)-row];
         }
         if (temp_sum != sum || temp_sum2 != sum) magic = false;

         /* Check that the numbers from 1 to n were used exactly once */
         for (int i=1; i<=(size*size); i++) {
            number_used[i] = false;
         }
         for (int row=0; row<size; row++) {
            for (int col=0; col<size; col++) {
               if (matrix[row][col] < 0 ||
                   matrix[row][col] > (size*size)) {
                  magic = false;
               }
               else {
                  number_used[matrix[row][col]] = true;
               }
            }
         }
         for (int i=1; i<=(size*size); i++) {
            if (!number_used[i]) magic = false;
         }

         /* Display the results */
         if (!magic) {
            System.out.println("This isn't a magic square.");
         }
         else {
            System.out.println("This magic square has sum = " + sum + ".");
         }
      }
   }
}

